<?php
declare(strict_types=1);
$root=dirname(__DIR__);$autoload=$root.'/vendor/autoload.php';$keysFile=$root.'/config/push-keys.php';if(!is_file($autoload)||!is_file($keysFile)){fwrite(STDERR,"Push no configurado.\n");exit(1);}require $autoload;$keys=require $keysFile;$c=require $root.'/config/database.php';$pdo=new PDO("mysql:host={$c['host']};dbname={$c['dbname']};charset={$c['charset']}",$c['user'],$c['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);
use Minishlink\WebPush\WebPush;use Minishlink\WebPush\Subscription;
$auth=['VAPID'=>['subject'=>$keys['subject'],'publicKey'=>$keys['publicKey'],'privateKey'=>$keys['privateKey']]];$webPush=new WebPush($auth,['TTL'=>3600,'urgency'=>'high','contentType'=>'application/json']);$webPush->setReuseVAPIDHeaders(true);
$events=$pdo->query("SELECT * FROM notification_events WHERE estado='PENDIENTE' AND intentos<5 ORDER BY created_at LIMIT 20")->fetchAll();foreach($events as$ev){$st=$pdo->prepare("SELECT ps.* FROM push_subscriptions ps JOIN usuarios u ON u.id=ps.usuario_id WHERE ps.activo=1 AND u.activo=1 AND u.rol='ADMIN'");$st->execute();$subs=$st->fetchAll();if(!$subs){$pdo->prepare("UPDATE notification_events SET intentos=intentos+1,last_error='Sin dispositivos ADMIN suscritos' WHERE id=:id")->execute([':id'=>$ev['id']]);continue;}$payload=json_encode(['tipo'=>$ev['tipo'],'title'=>$ev['titulo'],'body'=>$ev['cuerpo'],'url'=>$ev['url']?:'/dashboard.php','tag'=>'hache-'.$ev['tipo'].'-'.$ev['id'],'data'=>['event_id'=>$ev['id'],'alumno_id'=>$ev['alumno_id']]],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$map=[];foreach($subs as$s){$sub=Subscription::create(['endpoint'=>$s['endpoint'],'keys'=>['p256dh'=>$s['p256dh'],'auth'=>$s['auth']],'contentEncoding'=>$s['content_encoding']?:'aes128gcm']);$webPush->queueNotification($sub,$payload,['topic'=>'hache-new-user']);$map[$s['endpoint']]=$s['id'];}$ok=0;$err=[];foreach($webPush->flush() as$report){$ep=$report->getRequest()->getUri()->__toString();if($report->isSuccess()){$ok++;}else{$err[]=$report->getReason();if($report->isSubscriptionExpired()&&isset($map[$ep])){$pdo->prepare('UPDATE push_subscriptions SET activo=0 WHERE id=:id')->execute([':id'=>$map[$ep]]);}}}if($ok>0){$pdo->prepare("UPDATE notification_events SET estado='ENVIADO',sent_at=NOW(),intentos=intentos+1,last_error=:e WHERE id=:id")->execute([':e'=>$err?implode(' | ',$err):null,':id'=>$ev['id']]);echo "ENVIADO {$ev['tipo']} {$ev['id']} a $ok dispositivo(s)\n";}else{$pdo->prepare("UPDATE notification_events SET estado='ERROR',intentos=intentos+1,last_error=:e WHERE id=:id")->execute([':e'=>implode(' | ',$err)?:'No enviado',':id'=>$ev['id']]);}}
